@Entity(tableName = "notes")
data class NoteEntity(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val titre: String,
    @ColumnInfo(name = "module_id") val moduleId: String?,
)

@Dao
interface NoteDao {
    @Query("SELECT * FROM notes ORDER BY id DESC")
    fun observerTout(): Flow<List<NoteEntity>>

    @Query("SELECT * FROM notes WHERE module_id = :moduleId")
    suspend fun parModule(moduleId: String): List<NoteEntity>

    @Insert
    suspend fun ajouter(note: NoteEntity): Long

    @Update
    suspend fun modifier(note: NoteEntity)

    @Delete
    suspend fun supprimer(note: NoteEntity)
}

@Database(entities = [NoteEntity::class], version = 1)
abstract class BaseDeDonnees : RoomDatabase() {
    abstract fun notes(): NoteDao
}

fun creerBase(context: Context): BaseDeDonnees {
    return Room.databaseBuilder<BaseDeDonnees>(context, "academie.db")
        .setDriver(AndroidSQLiteDriver())
        .build()
}

