fun categorie(code: Int) = when (code) {
    in 200..299 -> "Succès"
    in 300..399 -> "Redirection"
    401 -> "Non authentifié"
    403 -> "Interdit"
    404 -> "Introuvable"
    429 -> "Trop de requêtes"
    in 400..499 -> "Erreur du client"
    in 500..599 -> "Erreur du serveur"
    else -> "Inconnu"
}

fun main() {
    listOf(200, 201, 304, 401, 404, 429, 503).forEach { code ->
        println("$code : ${categorie(code)}")
    }
}

