@Serializable
data class SortReseau(val id: Int, val nom: String)

interface ApiSorts {
    @GET("sorts")
    suspend fun lister(
        @Query("niveau") niveau: Int? = null,
    ): List<SortReseau>

    @GET("sorts/{id}")
    suspend fun lire(@Path("id") id: Int): SortReseau

    @POST("sorts")
    suspend fun creer(@Body sort: SortReseau): SortReseau

    @DELETE("sorts/{id}")
    suspend fun supprimer(@Path("id") id: Int): Response<Unit>
}

private val json = Json { ignoreUnknownKeys = true }

fun creerApi(): ApiSorts {
    val client = OkHttpClient.Builder()
        .connectTimeout(10, TimeUnit.SECONDS)
        .readTimeout(20, TimeUnit.SECONDS)
        .build()

    return Retrofit.Builder()
        .baseUrl("https://api.exemple.fr/")
        .client(client)
        .addConverterFactory(
            json.asConverterFactory("application/json".toMediaType())
        )
        .build()
        .create(ApiSorts::class.java)
}

suspend fun supprimerSort(api: ApiSorts, id: Int): Boolean {
    val reponse = api.supprimer(id)
    return reponse.isSuccessful
}

class FausseApi : ApiSorts {
    override suspend fun lister(niveau: Int?) = listOf(SortReseau(1, "Feu"))
    override suspend fun lire(id: Int) = SortReseau(id, "Feu")
    override suspend fun creer(sort: SortReseau) = sort
    override suspend fun supprimer(id: Int): Response<Unit> = Response.success(Unit)
}

