import java.io.IOException

sealed interface Resultat<out T> {
    data class Succes<T>(val valeur: T) : Resultat<T>
    data object SansReseau : Resultat<Nothing>
    data class ErreurServeur(val code: Int) : Resultat<Nothing>
}

class HttpErreur(val code: Int) : Exception()

suspend fun <T> appelSur(appel: suspend () -> T): Resultat<T> =
    try {
        Resultat.Succes(appel())
    } catch (e: IOException) {
        Resultat.SansReseau
    } catch (e: HttpErreur) {
        Resultat.ErreurServeur(e.code)
    }

fun message(resultat: Resultat<String>) = when (resultat) {
    is Resultat.Succes -> resultat.valeur
    Resultat.SansReseau -> "Vérifiez votre connexion."
    is Resultat.ErreurServeur -> "Service indisponible (${resultat.code})."
}

suspend fun main() {
    println(message(appelSur { "Bienvenue" }))
    println(message(appelSur { throw IOException() }))
    println(message(appelSur { throw HttpErreur(503) }))
}

import java.io.IOException
import kotlinx.coroutines.delay
import kotlinx.coroutines.runBlocking

suspend fun <T> avecTentatives(
    maximum: Int = 3,
    delaiInitial: Long = 10,
    bloc: suspend () -> T,
): T {
    var delaiCourant = delaiInitial
    repeat(maximum - 1) { essai ->
        try {
            return bloc()
        } catch (e: IOException) {
            println("Essai ${essai + 1} échoué, attente de $delaiCourant ms")
            delay(delaiCourant)
            delaiCourant *= 2
        }
    }
    return bloc()
}

fun main() = runBlocking {
    var appels = 0
    val resultat = avecTentatives {
        appels++
        if (appels < 3) throw IOException("réseau")
        "Réussi au troisième essai"
    }
    println(resultat)
}

