class IntercepteurJeton(private val lireJeton: () -> String?) : Interceptor {
    override fun intercept(chain: Interceptor.Chain): okhttp3.Response {
        val requete = chain.request()
        val jeton = lireJeton() ?: return chain.proceed(requete)

        return chain.proceed(
            requete.newBuilder()
                .header("Authorization", "Bearer $jeton")
                .build()
        )
    }
}

class Renouveleur(private val renouveler: () -> String?) : Authenticator {
    override fun authenticate(route: Route?, response: okhttp3.Response): Request? {
        if (response.request.header("X-Rejoue") != null) return null
        val jeton = renouveler() ?: return null

        return response.request.newBuilder()
            .header("Authorization", "Bearer $jeton")
            .header("X-Rejoue", "1")
            .build()
    }
}

