class CacheTemporaire<T>(
    private val dureeMs: Long,
    private val maintenant: () -> Long,
) {
    private var valeur: T? = null
    private var enregistreA = 0L

    fun lire(): T? {
        val perime = maintenant() - enregistreA > dureeMs
        return if (perime) null else valeur
    }

    fun ecrire(nouvelle: T) {
        valeur = nouvelle
        enregistreA = maintenant()
    }
}

fun main() {
    var horloge = 0L
    val cache = CacheTemporaire<String>(dureeMs = 1000) { horloge }

    cache.ecrire("Météo : pluie de météores")
    horloge = 500
    println(cache.lire())
    horloge = 1500
    println(cache.lire())
}

class SyncWorker(
    context: Context,
    parametres: WorkerParameters,
) : CoroutineWorker(context, parametres) {
    override suspend fun doWork(): Result {
        return try {
            synchroniser()
            Result.success()
        } catch (e: IOException) {
            Result.retry()
        }
    }
}

fun planifierSync(context: Context) {
    val requete = OneTimeWorkRequestBuilder<SyncWorker>()
        .setConstraints(
            Constraints.Builder()
                .setRequiredNetworkType(NetworkType.CONNECTED)
                .build()
        )
        .build()

    WorkManager.getInstance(context).enqueueUniqueWork(
        "synchronisation",
        ExistingWorkPolicy.KEEP,
        requete,
    )
}
